Solution B: function createVoiceRacingGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;

    // UI Elements
    const startBtn = document.createElement('button');
    startBtn.textContent = 'Start Race';
    document.body.appendChild(startBtn);
    const muteBtn = document.createElement('button');
    muteBtn.textContent = 'Mute';
    document.body.appendChild(muteBtn);
    const volumeMeter = document.createElement('canvas');
    volumeMeter.width = 200;
    volumeMeter.height = 20;
    document.body.appendChild(volumeMeter);
    const vmCtx = volumeMeter.getContext('2d');

    // Game state
    let audioCtx, analyser, dataArray, micStream;
    let muted = false;
    let running = false;
    let lapCount = 0;
    const totalLaps = 3;
    let startTime = 0;
    let lapStartTime = 0;
    let bestLap = localStorage.getItem('voiceRacingBest') ? parseFloat(localStorage.getItem('voiceRacingBest')) : null;
    let car = { theta: 0, speed: 0 };
    const obstacles = [];
    const obstacleCount = 8;
    const trackRadiusX = 150, trackRadiusY = 100;
    const centerX = canvas.width / 2, centerY = canvas.height / 2;
    const crashCooldown = 0;
    let lastCrash = 0;

    // Initialize obstacles
    for (let i = 0; i < obstacleCount; i++) {
        const angle = (i + 1) * (2 * Math.PI) / (obstacleCount + 1);
        obstacles.push({ angle });
    }

    // Audio setup
    async function initAudio() {
        try {
            micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
            audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            const source = audioCtx.createMediaStreamSource(micStream);
            analyser = audioCtx.createAnalyser();
            analyser.fftSize = 256;
            dataArray = new Float32Array(analyser.fftSize);
            source.connect(analyser);
        } catch (e) {
            alert('Microphone access denied. Game cannot run.');
        }
    }

    function getVolume() {
        if (!analyser || muted) return 0;
        analyser.getFloatTimeDomainData(dataArray);
        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) {
            sum += dataArray[i] * dataArray[i];
        }
        const rms = Math.sqrt(sum / dataArray.length);
        return rms;
    }

    function drawTrack() {
        ctx.save();
        ctx.translate(centerX, centerY);
        ctx.beginPath();
        ctx.ellipse(0, 0, trackRadiusX, trackRadiusY, 0, 0, 2 * Math.PI);
        ctx.strokeStyle = '#555';
        ctx.lineWidth = 5;
        ctx.stroke();
        ctx.restore();
    }

    function drawObstacles() {
        obstacles.forEach(o => {
            const x = centerX + trackRadiusX * Math.cos(o.angle);
            const y = centerY + trackRadiusY * Math.sin(o.angle);
            ctx.fillStyle = 'brown';
            ctx.beginPath();
            ctx.arc(x, y, 8, 0, 2 * Math.PI);
            ctx.fill();
        });
    }

    function drawCar() {
        const x = centerX + trackRadiusX * Math.cos(car.theta);
        const y = centerY + trackRadiusY * Math.sin(car.theta);
        ctx.fillStyle = 'red';
        ctx.beginPath();
        ctx.arc(x, y, 10, 0, 2 * Math.PI);
        ctx.fill();
    }

    function drawVolumeMeter(vol) {
        vmCtx.clearRect(0, 0, volumeMeter.width, volumeMeter.height);
        vmCtx.fillStyle = 'green';
        const width = Math.min(vol * 500, volumeMeter.width);
        vmCtx.fillRect(0, 0, width, volumeMeter.height);
    }

    function updateCar(delta) {
        const vol = getVolume();
        const targetSpeed = Math.min(0.005 + vol * 0.5, 0.03);
        car.speed += (targetSpeed - car.speed) * 0.1;
        car.theta += car.speed * delta;
        if (car.theta > 2 * Math.PI) car.theta -= 2 * Math.PI;
    }

    function checkCollision() {
        const now = performance.now();
        if (now - lastCrash < 500) return;
        const carX = centerX + trackRadiusX * Math.cos(car.theta);
        const carY = centerY + trackRadiusY * Math.sin(car.theta);
        for (let i = 0; i < obstacles.length; i++) {
            const o = obstacles[i];
            const ox = centerX + trackRadiusX * Math.cos(o.angle);
            const oy = centerY + trackRadiusY * Math.sin(o.angle);
            const dx = carX - ox, dy = carY - oy;
            const dist = Math.hypot(dx, dy);
            if (dist < 18) {
                car.speed = Math.max(car.speed * -0.3, -0.01);
                lastCrash = now;
                break;
            }
        }
    }

    function checkLap() {
        if (car.theta < 0.1 && car.speed > 0) {
            const now = performance.now();
            const lapTime = (now - lapStartTime) / 1000;
            if (bestLap === null || lapTime < bestLap) {
                bestLap = lapTime;
                localStorage.setItem('voiceRacingBest', bestLap);
            }
            lapCount++;
            lapStartTime = now;
            if (lapCount >= totalLaps) {
                running = false;
                celebrate();
            }
        }
    }

    function celebrate() {
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'yellow';
        ctx.font = '30px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Race Finished!', canvas.width / 2, canvas.height / 2 - 20);
        ctx.fillText(`Best Lap: ${bestLap.toFixed(2)}s`, canvas.width / 2, canvas.height / 2 + 20);
    }

    function gameLoop(timestamp) {
        const now = performance.now();
        const delta = now - (gameLoop.lastTime || now);
        gameLoop.lastTime = now;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawTrack();
        drawObstacles();
        if (running) {
            updateCar(delta);
            checkCollision();
            checkLap();
        }
        drawCar();
        const vol = getVolume();
        drawVolumeMeter(vol);
        if (running) requestAnimationFrame(gameLoop);
    }

    startBtn.onclick = () => {
        if (!audioCtx) initAudio().then(() => {
            startRace();
        });
        else startRace();
    };

    function startRace() {
        running = true;
        lapCount = 0;
        car.theta = 0;
        car.speed = 0;
        startTime = performance.now();
        lapStartTime = startTime;
        requestAnimationFrame(gameLoop);
    }

    muteBtn.onclick = () => {
        muted = !muted;
        muteBtn.textContent = muted ? 'Unmute' : 'Mute';
    };
}

